#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# SKU-9 is a catalog SKU and must be reported even when it had no movements.

if [ ! -f movements.log ]; then
    echo "stock.sh: movements.log is required" >&2
    exit 1
fi

awk '
    {
        net[$1] += ($2 == "receipt" ? $3 : -$3)
    }
    END {
        net["SKU-9"] += 0
        for (sku in net)
            print sku, net[sku]
    }
' movements.log | LC_ALL=C sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# SKU-9 is a catalog SKU and must be reported even when it had no movements.

# An absent log represents a day with no recorded movements.  Use /dev/null
# rather than inventing a movement record.
input=movements.log
if [ ! -f "$input" ]; then
    input=/dev/null
fi

awk '
    {
        net[$1] += ($2 == "receipt" ? $3 : -$3)
    }
    END {
        net["SKU-9"] += 0
        for (sku in net)
            print sku, net[sku]
    }
' "$input" | LC_ALL=C sort > stock.txt
